export async function saveRecord(id,kind,owner,data){const old=globalThis.storeTest.rows.get(id);if(old&&(old.kind!==kind||old.owner!==owner))throw Error('ownership');const at=new Date().toISOString();globalThis.storeTest.rows.set(id,{id,kind,owner,data:structuredClone(data),created:old?.created||at,updated:at})}
