export async function compareAndSet(previous,data){const old=globalThis.storeTest.rows.get(previous.id);if(!old||old.kind!==previous.kind||old.owner!==previous.owner||JSON.stringify(old.data)!==JSON.stringify(previous.data))return false;await saveRecord(old.id,old.kind,old.owner,data);return true}
export async function saveCatalogueProduct(previous,data){
 const state=globalThis.storeTest,old=state.rows.get(data.id);
 if(old&&(old.kind!=='product'||old.owner!=='store'||!previous||JSON.stringify(old.data)!==JSON.stringify(previous.data)||old.data.archivedAt)||!old&&previous)return {ok:false,reason:'version'};
 const claims=[{sku:data.sku,variationId:null},...(data.variations||[]).map(v=>({sku:v.sku,variationId:v.id}))];
 if(new Set(claims.map(c=>c.sku)).size!==claims.length)return {ok:false,reason:'sku'};
 for(const c of claims){const held=state.rows.get('product-sku:'+c.sku);if(held&&(held.kind!=='setting'||held.owner!=='catalog:sku'||held.data.productId!==data.id||(held.data.variationId||null)!==c.variationId))return {ok:false,reason:'sku'};if([...state.rows.values()].some(r=>r.kind==='product'&&r.id!==data.id&&(r.data.sku||r.id)===c.sku))return {ok:false,reason:'sku'}}
 const now=new Date().toISOString();for(const c of claims)state.rows.set('product-sku:'+c.sku,{id:'product-sku:'+c.sku,kind:'setting',owner:'catalog:sku',data:{productId:data.id,variationId:c.variationId},created:now,updated:now});state.rows.set(data.id,{id:data.id,kind:'product',owner:'store',data:structuredClone(data),created:old?.created||now,updated:now});return {ok:true};
}
