function seedDirectory(user,role){const old=globalThis.storeTest.rows.get('staff:directory')?.data,members={...old?.members,[user.email]:{email:user.email,role,active:true,identityId:user.userId,status:'Active',onboardedAt:'2026-11-10T00:00:00Z'}};seed('staff:directory','setting','store',{version:1,members,createdAt:'2026-11-10T00:00:00Z'})}
function adminCookie(){const u=globalThis.storeTest.user;if(u?.authProvider!=='email')return '';const id=u.userId.slice(6),token=createHash('sha256').update('synthetic-session:'+u.userId).digest('hex'),hash=v=>createHash('sha256').update(v).digest('hex'),now=Date.now();seed('email-user:'+hash(u.email),'setting','auth:directory',{id,email:u.email});seed('email-session:'+hash(token),'setting','auth:sessions',{id:'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',userId:id,email:u.email,scope:'admin',createdAt:now,expiresAt:now+3600000,...(globalThis.storeTest.activeSession===false?{revokedAt:now}:{})});return ADMIN_COOKIE+'='+token}
const originalFetch=globalThis.fetch;
globalThis.fetch=async(input,init)=>{const target=String(input);if(target.startsWith('https://example.supabase.co/auth/v1/')){if(target.includes('/otp'))return Response.json({user:null,session:null});if(target.includes('/logout'))return new Response(null,{status:204});if(target.endsWith('/user')){const u=globalThis.storeTest.user;if(u?.authProvider==='email')return Response.json(emailProfile(u.email,u.userId.slice(6)));return Response.json({msg:'No verified user'}, {status:401})}throw Error('Unexpected synthetic auth call: '+target)}return originalFetch(input,init)};
