test('contact enquiries require a subject and persist a safe, idempotent customer record',async()=>{
 reset();const key=crypto.randomUUID();
 const first=await post('enquiry',{idempotencyKey:key,data:{...enquiryData,subject:'  Ring sizing help  ',status:'Resolved',staffNotes:'injected',response:'injected',owner:'someone-else'}});
 assert.equal(first.status,200);const receipt=await first.json();assert.match(receipt.reference,/^WS-E-[A-F0-9]{12}$/);
 const row=globalThis.storeTest.rows.get(receipt.id);assert.equal(row.owner,'customer-one');assert.equal(row.data.subject,enquiryData.subject);assert.equal(row.data.status,'Open');assert.equal(row.data.staffNotes,undefined);assert.equal(row.data.response,undefined);
 assert.equal((await post('enquiry',{idempotencyKey:key,data:enquiryData})).status,200);assert.equal([...globalThis.storeTest.rows.values()].filter(r=>r.kind==='enquiry').length,1);
 assert.equal((await post('enquiry',{idempotencyKey:key,data:{...enquiryData,subject:'A different enquiry'}})).status,409);
 for(const subject of ['', '  ', 'ab', 'a'.repeat(151), 'Subject\nInjected header'])assert.equal((await post('enquiry',{idempotencyKey:crypto.randomUUID(),data:{...enquiryData,subject}})).status,400);
 assert.equal((await post('enquiry',{idempotencyKey:'invalid',data:enquiryData})).status,400);
 reset(null);assert.equal((await post('enquiry',{idempotencyKey:key,data:enquiryData})).status,401);
});

