test('scheduled products, images and requests become available only at the selected publication instant',async()=>{
 manager();const data={...newProduct(),attributes:[{id:crypto.randomUUID(),name:'Main Stone Depth',values:['6 mm']}],imageIds:productMedia(),publishAt:new Date(Date.now()+3600000).toISOString()};let response=await post('product',{create:true,intent:'schedule',data});assert.equal(response.status,200,JSON.stringify(await response.clone().json()));assert.equal((await getProducts()).some(p=>p.id===data.id),false);assert.equal(await productExists(data.id),false);assert.equal((await readMedia(data.imageIds[0])).status,404);assert.equal((await getProducts(true)).find(p=>p.id===data.id).attributes[0].values[0],'6 mm');
 const clock=Date.now;try{Date.now=()=>Date.parse(data.publishAt);assert.equal(await productExists(data.id),true);const live=(await getProducts()).find(p=>p.id===data.id);assert.ok(live);assert.equal(matchesSearch(live,'6 mm'),true);assert.equal((await readMedia(data.imageIds[0])).status,200)}finally{Date.now=clock}
 response=await post('product',{intent:'schedule',data:{id:data.id,publishAt:'2020-01-01T00:00:00Z'}});assert.equal(response.status,400);assert.equal((await post('product',{intent:'publish',data:{id:data.id}})).status,200);assert.equal(globalThis.storeTest.rows.get(data.id).data.publishAt,null);assert.equal(await productExists(data.id),true);
});
test('incomplete attributes save as drafts but cannot publish and quantity settings persist privately and publicly',async()=>{
 manager();const data={...newProduct(),attributes:[{id:crypto.randomUUID(),name:'',values:[]}],volumePricingEnabled:true,quantityDiscounts:[{minimum:2,percent:10},{minimum:4,percent:20}]};assert.equal((await post('product',{create:true,intent:'draft',data})).status,200);assert.equal((await post('product',{intent:'publish',data:{id:data.id,imageIds:productMedia()}})).status,400);assert.equal((await post('product',{intent:'publish',data:{id:data.id,attributes:[{id:data.attributes[0].id,name:'Theme',values:['Calligraphy']}],imageIds:productMedia()}})).status,200);const live=(await getProducts()).find(p=>p.id===data.id);assert.deepEqual(live.quantityDiscounts,data.quantityDiscounts);assert.equal(live.attributes[0].values[0],'Calligraphy');assert.equal(live.price,null);
});
test('server quantity pricing rejects an undiscounted order and records calculated discounts in any agreed currency',async()=>{
 manager();globalThis.storeTest.rows.get('supplier-one').data.capacity=100;const data={...newProduct(),price:1000,volumePricingEnabled:true,quantityDiscounts:[{minimum:2,percent:10},{minimum:4,percent:20}],imageIds:productMedia()};assert.equal((await post('product',{create:true,intent:'publish',data})).status,200);const item={productId:data.id,size:'9',engraving:'Plain'},details={...manualDetails(),items:[item,item],amount:2100,shipping:100};assert.equal((await adminPost('manual-order',{data:details})).status,400);let response=await adminPost('manual-order',{data:{...details,amount:1900}});assert.equal(response.status,200,JSON.stringify(await response.clone().json()));const order=globalThis.storeTest.rows.get((await response.json()).id);assert.equal(order.data.quantityPricing.discountMinor,20000);assert.equal(order.data.amountMinor,190000);
 const foreign={...details,key:crypto.randomUUID(),currency:'USD',amount:19,shipping:1,unitPrices:[{key:data.id+':',amountMinor:1000}]};response=await adminPost('manual-order',{data:foreign});assert.equal(response.status,200,JSON.stringify(await response.clone().json()));const usd=globalThis.storeTest.rows.get((await response.json()).id);assert.equal(usd.data.quantityPricing.totalMinor,1800);assert.equal(usd.data.quantityPricing.currency,'USD');assert.equal((await adminPost('manual-order',{data:{...foreign,key:crypto.randomUUID(),unitPrices:[{key:'invented',amountMinor:1000}]}})).status,400);
});
